const { trace, context, propagation } = require('@opentelemetry/api');

const tracer = trace.getTracer('cart-service');

async function handleAddToCart(req, res) {
  const span = tracer.startSpan('cart.addItem');

  await context.with(trace.setSpan(context.active(), span), async () => {
    span.setAttribute('item.id', req.body.itemId);

    // Inject the current trace context into outgoing headers,
    // this is what turns into the traceparent header on the wire.
    const headers = {};
    propagation.inject(context.active(), headers);

    const response = await fetch('http://inventory-service/reserve', {
      method: 'POST',
      headers,
      body: JSON.stringify({ itemId: req.body.itemId }),
    });

    if (!response.ok) {
      span.setAttribute('error', true);
    }

    span.end();
  });

  res.send('ok');
}

